import {
  searchWords,
  SpokenLanguage,
  SupportedLanguages,
} from "../spoken-language/SpokenLanguage";

import data from "./languages.json";

export interface OmnilingualLanguage {
  code: string;
  name: string;
  script: string;
}

export const isOmnilingual = (
  language: SpokenLanguage | OmnilingualLanguage,
): language is OmnilingualLanguage => "script" in language;

// Generated by scripts/omnilingual/build-languages.js, already A to Z.
// Rows are [ISO 639-3 code, name, script, ISO name when it differs].
const rows = data as string[][];
const all: OmnilingualLanguage[] = rows.map(([code, name, script]) => ({
  code,
  name,
  script,
}));
let words: string[] | null = null;

export const OmnilingualLanguages = {
  all,

  /** Matches the start of any word in the name or ISO name, in English. */
  search(query: string): OmnilingualLanguage[] {
    const needle = searchWords(query);
    if (needle === " ") return all;
    words ??= rows.map(([, name, , isoName]) =>
      isoName ? searchWords(name) + searchWords(isoName) : searchWords(name),
    );
    return all.filter((_, i) => words![i].includes(needle));
  },

  /** Search results, but only when no other model covers a match:
   *  SupportedLanguages holds every other model's languages. */
  fallback(query: string): OmnilingualLanguage[] {
    return SupportedLanguages.search(SupportedLanguages.all, query).length
      ? []
      : OmnilingualLanguages.search(query);
  },
};
